<script setup lang="ts">
/**
 * Filtered single choice (`design/components/combobox.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/combobox.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/combobox'
import { normalizeProps, useMachine } from '@zag-js/vue'

import { Icon, agentMember, useDirection, useMediaQuery } from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/controls/combobox.module.css'
import sheet from '@polymorph/recipes/overlays/sheet.module.css'
import Skeleton from '../structure/Skeleton.vue'

export type ComboboxFilter = NonNullable<ComboboxProps['filter']>

export interface ComboboxOption {
  value: string
  label: string
  description?: string
  disabled?: boolean
}

export interface ComboboxMessages {
  showOptions?: string
  clear?: string
  loadingOptions?: string
  options?: (count: number) => string
  list?: string
}

export interface ComboboxProps {
  /**
   * Keeps free text. Blur keeps the draft instead of restoring the selected label. A commit that
   * matches nothing sets the *selection* to `null` and keeps the text, which the app reads
   * through the controlled `inputValue` pair (React Aria's semantics, passed through). `name`
   * then serializes the typed text whenever no option is selected.
   */
  allowsCustomValue?: boolean
  ariaDescribedby?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Input's clear button. Clearing reports `onChange(null)`.
   */
  clearable?: boolean
  /**
   * Opens on mount, for galleries and tests. Screens let the user open it.
   */
  defaultOpen?: boolean
  defaultValue?: string | null
  disabled?: boolean
  /**
   * Apps localize by passing it. An empty dropdown shows one line of text, not an illustration.
   */
  emptyMessage?: string
  filter?: false | 'contains' | 'startsWith'
  id?: string
  /**
   * The controlled input text, which async apps use to drive their queries.
   */
  inputValue?: string
  invalid?: boolean
  /**
   * Async loading state: skeleton rows in the panel and a spinning glyph in the field.
   */
  loading?: boolean
  /**
   * The member's strings. See `ComboboxMessages`.
   */
  messages?: ComboboxMessages
  /**
   * Serializes the *selected value*, not the typed text.
   */
  name?: string
  /**
   * The *current* list. In async use, the app supplies a new list for each query.
   */
  options: ComboboxOption[]
  placeholder?: string
  /**
   * `'auto'` shows the popup as a sheet below `30rem` (the conventions' sheet presentation).
   * `'popover'` keeps the popover at every width. There is no always-sheet value, because the
   * closed union does not allow one (`docs/layout.md`).
   */
  presentation?: 'auto' | 'popover'
  size?: 'sm' | 'md' | 'lg'
  /**
   * Selection only by default. Free text that matches nothing resolves to `null` on blur, and
   * the input restores the selected label. `allowsCustomValue` below is the explicit opt-in, not
   * a hidden mode of this pair.
   */
  value?: string | null
}

defineOptions({ name: 'Combobox', inheritAttrs: false })

const props = withDefaults(defineProps<ComboboxProps>(), {
  allowsCustomValue: false,
  ariaRequired: undefined,
  clearable: false,
  defaultOpen: undefined,
  disabled: false,
  emptyMessage: 'No results',
  filter: 'contains',
  invalid: false,
  loading: false,
  presentation: 'auto',
  size: 'md',
})
const emit = defineEmits<{
  blur: [event: FocusEvent]
  change: [value: string | null]
  inputChange: [value: string]
  loadMore: []
}>()
const uid = useId()
const query = ref(
  props.options.find((option) => option.value === (props.value ?? props.defaultValue))?.label ?? '',
)
const showAll = ref(false)
const loadMoreAt = ref(-1)
const input = useTemplateRef<HTMLElement>('input')
const list = useTemplateRef<HTMLElement>('list')
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const sheetPanel = useTemplateRef<HTMLElement>('sheetPanel')
const phone = useMediaQuery('phone')
const sheeting = computed(() => props.presentation === 'auto' && phone.value)
const say = computed(() => ({
  showOptions: 'Show options',
  clear: 'Clear',
  loadingOptions: 'Loading options…',
  options: (count: number) => `${count} options`,
  list: 'Suggestions',
  ...props.messages,
}))
const collator = computed(
  () => new Intl.Collator(undefined, { usage: 'search', sensitivity: 'base' }),
)
const needle = computed(() => (props.inputValue ?? query.value).normalize('NFC'))
const matches = computed(
  () => (label: string) =>
    ((text: string) =>
      needle.value === '' ||
      (props.filter === 'startsWith'
        ? collator.value.compare(text.slice(0, needle.value.length), needle.value) === 0
        : Array.from({ length: Math.max(0, text.length - needle.value.length + 1) }, (_, at) =>
            text.slice(at, at + needle.value.length),
          ).some((part) => collator.value.compare(part, needle.value) === 0)))(
      label.normalize('NFC'),
    ),
)
const shown = computed(() =>
  props.filter === false || showAll.value
    ? props.options
    : props.options.filter((option) => matches.value(option.label)),
)
const lastEnabled = computed(
  () => shown.value.findLast((option) => option.disabled !== true)?.value,
)
const requestMore = computed(
  () => () =>
    !props.loading &&
    loadMoreAt.value !== props.options.length &&
    ((loadMoreAt.value = props.options.length), emit('loadMore'), true),
)
const emitBlur = computed(() => (event: FocusEvent) => setTimeout(() => emit('blur', event)))
const documentDirection = useDirection(() => input.value)
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    collection: zag.collection({
      items: shown.value,
      itemToValue: (item) => item.value,
      itemToString: (item) => item.label,
      isItemDisabled: (item) => item.disabled === true,
    }),
    value: props.value === undefined ? undefined : props.value === null ? [] : [props.value],
    defaultValue: props.defaultValue == null ? undefined : [props.defaultValue],
    inputValue: props.inputValue,
    defaultOpen: props.defaultOpen,
    disabled: props.disabled,
    invalid: props.invalid,
    placeholder: props.placeholder,
    allowCustomValue: props.allowsCustomValue,
    inputBehavior: 'autohighlight' as const,
    positioning: { placement: 'bottom-start' as const, gutter: 2, sameWidth: false },
    ids: props.id === undefined ? undefined : { input: props.id },
    onPointerDownOutside: (event) =>
      panel.value?.contains(event.detail.originalEvent.target as Node) && event.preventDefault(),
    onValueChange: (details) => {
      emit('change', details.value[0] ?? null)
    },
    onInputValueChange: (details) => {
      ;((query.value = details.inputValue),
        details.reason === 'input-change' && (showAll.value = false),
        emit('inputChange', details.inputValue))
    },
    onOpenChange: (details) => {
      ;((showAll.value =
        details.open && (details.reason === 'trigger-click' || details.reason === 'arrow-key')),
        !details.open && details.reason === 'escape-key' && revert.value())
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const revert = computed(
  () => () =>
    (props.allowsCustomValue && api.value.value.length === 0) ||
    api.value.setInputValue(
      props.options.find((option) => option.value === api.value.value[0])?.label ?? '',
    ),
)
const showClear = computed(() => props.clearable && api.value.inputValue !== '' && !props.disabled)
const showEmpty = computed(() => api.value.open && !props.loading && shown.value.length === 0)
const announcement = computed(() =>
  !api.value.open
    ? ''
    : props.loading
      ? say.value.loadingOptions
      : shown.value.length === 0
        ? props.emptyMessage
        : say.value.options(shown.value.length),
)
const formValue = computed(
  () => api.value.value[0] ?? (props.allowsCustomValue ? api.value.inputValue : ''),
)
const present = usePresence(() => api.value.open && !sheeting.value, panel)
const sheetPresent = usePresence(
  () => api.value.open && sheeting.value,
  sheetPanel,
  'sheet.panel',
  { sheetSide: 'bottom' },
)
const scrimPresent = usePresence(() => api.value.open && sheeting.value, scrim, 'dialog.scrim')
const effect1 = () => {
  api.value.open &&
    api.value.highlightedValue === null &&
    ((next) => next !== undefined && api.value.setHighlightValue(next))(
      api.value.value.find((chosen) => shown.value.some((option) => option.value === chosen)) ??
        shown.value.find((option) => option.disabled !== true)?.value,
    )
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
const effect2 = () => {
  api.value.open &&
    api.value.highlightedValue !== null &&
    api.value.highlightedValue === lastEnabled.value &&
    requestMore.value()
}
onMounted(effect2)
watch(() => api.value.highlightedValue, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Combobox',
    element: () => input.value,
    state: () => ({
      value: api.value.value[0] ?? null,
      options: props.options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      'input-value': api.value.inputValue,
      open: api.value.open,
      disabled: props.disabled,
      invalid: props.invalid,
    }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (api.value.value[0] === value) return
            api.value.setValue([value])
            api.value.setInputValue(
              props.options.find((option) => option.value === value)?.label ?? '',
            )
          })(),
      },
      fill: { argument: 'text', run: (value) => api.value.setInputValue(value) },
      clear: () => (api.value.setValue([]), api.value.setInputValue('')),
      open: () => api.value.setOpen(true, 'trigger-click'),
      close: () => api.value.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    :class="styles.field"
    :id="api.getControlProps().id"
    :data-size="size"
    :data-state="api.open ? 'open' : 'closed'"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-loading="loading ? '' : undefined"
    :data-sheeting="sheeting && api.open ? '' : undefined"
    data-member="combobox"
  >
    <!-- trigger -->
    <input
      ref="input"
      v-bind="api.getInputProps()"
      :class="styles.input"
      :name="undefined"
      :required="undefined"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      @keydown="
        $event.key === 'Tab' &&
        api.open &&
        api.highlightedValue !== null &&
        api.selectValue(api.highlightedValue)
      "
      @focusout="emitBlur($event)"
    />
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="formValue"
      :disabled="disabled || undefined"
    />
    <!-- clear -->
    <button
      v-if="showClear"
      :class="styles.clear"
      type="button"
      :aria-label="say.clear"
      @click="(api.clearValue(), api.focus())"
    >
      <Icon name="clear" :size="size" />
    </button>
    <!-- chevron -->
    <button v-bind="api.getTriggerProps()" :class="styles.chevron" :aria-label="say.showOptions">
      <span v-if="loading" :class="styles.spinner">
        <Icon name="loading" :size="size" />
      </span>
      <Icon v-else name="expand" :size="size" />
    </button>
    <div :class="styles.status" role="status" aria-live="polite">
      {{ announcement }}
    </div>
  </div>
  <Teleport to="body">
    <div v-if="present" v-bind="api.getPositionerProps()">
      <!-- panel -->
      <div
        ref="panel"
        :class="styles.content"
        :style="{
          '--radix-popover-trigger-width': 'var(--reference-width)',
          '--radix-popover-content-available-height': 'var(--available-height)',
          '--radix-popover-content-transform-origin': 'var(--transform-origin)',
        }"
        :data-size="size"
        :data-state="api.open ? 'open' : 'closed'"
        data-member="combobox"
      >
        <!-- list -->
        <ul
          ref="list"
          v-bind="api.getContentProps()"
          :class="styles.listbox"
          :hidden="undefined"
          :aria-label="say.list"
          :aria-labelledby="
            ariaLabelledby === undefined
              ? undefined
              : `${api.getContentProps().id} ${ariaLabelledby}`
          "
          @scroll="
            (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <= 32 &&
            requestMore()
          "
        >
          <template v-for="option in shown" :key="option.value">
            <!-- option -->
            <li v-bind="api.getItemProps({ item: option })" :class="styles.option">
              <span :class="styles.check">
                <Icon v-if="api.value.includes(option.value)" name="confirm" size="sm" />
              </span>
              <span :class="styles.text">
                <span :class="styles.label">
                  {{ option.label }}
                </span>
                <span v-if="option.description !== undefined" :class="styles.description">
                  {{ option.description }}
                </span>
              </span>
            </li>
          </template>
        </ul>
        <div v-if="loading" :class="styles.rows" aria-hidden="true">
          <template v-for="row in [0, 1, 2]" :key="row">
            <div :class="styles.row">
              <Skeleton textStep="sm" />
            </div>
          </template>
        </div>
        <div v-if="showEmpty" :class="styles.empty" aria-hidden="true">
          {{ emptyMessage }}
        </div>
      </div>
    </div>
    <div
      v-if="scrimPresent"
      ref="scrim"
      :class="sheet.scrim"
      :data-state="api.open ? 'open' : 'closed'"
    />
    <div v-if="sheetPresent" :class="sheet.positioner">
      <div
        ref="sheetPanel"
        :class="sheet.panel"
        data-presentation="sheet"
        :data-state="api.open ? 'open' : 'closed'"
      >
        <!-- panel -->
        <div ref="panel" :class="styles.sheetBody" :data-size="size" data-member="combobox">
          <!-- list -->
          <ul
            ref="list"
            v-bind="api.getContentProps()"
            :class="styles.listbox"
            :hidden="undefined"
            :aria-label="say.list"
            :aria-labelledby="
              ariaLabelledby === undefined
                ? undefined
                : `${api.getContentProps().id} ${ariaLabelledby}`
            "
            @scroll="
              (list?.scrollHeight ?? 0) - (list?.scrollTop ?? 0) - (list?.clientHeight ?? 0) <=
                32 && requestMore()
            "
          >
            <template v-for="option in shown" :key="option.value">
              <!-- option -->
              <li v-bind="api.getItemProps({ item: option })" :class="styles.option">
                <span :class="styles.check">
                  <Icon v-if="api.value.includes(option.value)" name="confirm" size="sm" />
                </span>
                <span :class="styles.text">
                  <span :class="styles.label">
                    {{ option.label }}
                  </span>
                  <span v-if="option.description !== undefined" :class="styles.description">
                    {{ option.description }}
                  </span>
                </span>
              </li>
            </template>
          </ul>
          <div v-if="loading" :class="styles.rows" aria-hidden="true">
            <template v-for="row in [0, 1, 2]" :key="row">
              <div :class="styles.row">
                <Skeleton textStep="sm" />
              </div>
            </template>
          </div>
          <div v-if="showEmpty" :class="styles.empty" aria-hidden="true">
            {{ emptyMessage }}
          </div>
        </div>
      </div>
    </div>
  </Teleport>
</template>
